Here's a Python function `match_parens` that checks if it's possible to concatenate two given strings of parentheses to form a balanced string. A string is considered balanced if every opening parenthesis '(' has a corresponding closing parenthesis ')' in the correct order.

```python
def match_parens(lst):
    def is_balanced(s):
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            elif char == ')':
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    # Try concatenating in both possible orders
    if is_balanced(lst[0] + lst[1]) or is_balanced(lst[1] + lst[0]):
        return 'Yes'
    else:
        return 'No'

# Example usage:
print(match_parens(['()(', ')']))  # Output: 'Yes'
print(match_parens([')', ')']))     # Output: 'No'
```

