def compare_one(a, b):
    # Helper function to convert strings with '.' or ',' to float
    def to_float(num):
        if isinstance(num, str):
            num = num.replace(',', '.')
        return float(num)

    # Convert both a and b to float for comparison
    a_float = to_float(a)
    b_float = to_float(b)

    # Compare and return the larger value in its original type
    if a_float > b_float:
        return a
    elif a_float < b_float:
        return b
    else:
        return None
