def special_factorial(n):
    # Helper function to calculate factorial
    def factorial(x):
        if x == 0:
            return 1
        else:
            return x * factorial(x - 1)

    # Calculate the special factorial
    result = 1
    for i in range(1, n + 1):
        result *= factorial(i)

    return result
