def fix_spaces(text):
    # Initialize an empty list to store the result
    result = []
    # Initialize a counter for consecutive spaces
    consecutive_spaces = 0
    # Iterate through each character in the text
    for char in text:
        if char == " ":
            # Increment the counter if the character is a space
            consecutive_spaces += 1
        else:
            # If the counter is 0, add the character as is
            if consecutive_spaces == 0:
                result.append(char)
            # If the counter is 2 or more, add "-" to the result
            elif consecutive_spaces >= 2:
                result.append('-')
            # Reset the counter if the character is not a space
            consecutive_spaces = 0
    # Add the last group of spaces to the result if any
    if consecutive_spaces == 0:
        result.append(text[-1])
    elif consecutive_spaces >= 2:
        result.append('-')
    # Join the result list into a string and return it
    return ''.join(result)
```

