def words_in_sentence(sentence):
    """
    Returns a string of words from the input sentence whose lengths are prime numbers.
    The words are returned in the order they appear in the input sentence.
    """
    def is_prime(n):
        """Check if a number is prime."""
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    return ' '.join(word for word in words if is_prime(len(word)))

