def solve(s):
    if not any(char.isalpha() for char in s):
        return s[::-1]

    result = []
    for char in s:
        if char.isalpha():
            if char.islower():
                result.append(char.upper())
            else:
                result.append(char.lower())
        else:
            result.append(char)

    return ''.join(result)
